f = imread('Fig0516(a)(appl017_boulder_noisy).tif');
F = fftshift(fft2(f));          % 移频（将低频移到中心）
[M, N] = size(F);               % 获取频谱尺寸
d0 = 30;                        % 截止频率（与原代码一致）
n = 2;                          % 巴特沃斯滤波器的阶数（可调整，如n=1,2,3...）
n1 = floor(M/2);                % 频谱中心行坐标
n2 = floor(N/2);                % 频谱中心列坐标

for u = 1:M
    for v = 1:N
       D(u,v)
        d = sqrt((u - n1)^2 + (v - n2)^2);
            h = 1 / (1 + (d / d0)^(2 * n));  
        G(u, v) = h * F(u, v);  
    end
end

G = ifftshift(G);               % 反向移频（恢复原始频谱布局）
g = uint8(real(ifft2(G)));      % 逆傅里叶变换 + 取实部 + 转为8位图像
imshow(g);
title(['BLPF滤波 (d0=', num2str(d0), ', n=', num2str(n), ')']);
